insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SCI-COM-01','science-knowledge','Community','Know community helpers','Match helpers to what they do or use.','little-explorer','["Matches helper to tool"]'::jsonb,'{"priorKnowledge":"Knows common jobs.","examples":["Doctor and stethoscope"],"activityTypes":["match-pair"],"commonDifficulties":["Unfamiliar jobs"],"hints":["What does this helper use?"],"nextSteps":[],"parentExplanation":"Understanding who helps us builds trust and community awareness.","offlineIdea":"Say thank you to a helper you meet today."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
