ompt":"How many apples?","visual":"🍎","total":3,"choices":[2,3,4],"hints":["Touch each apple once.","The last number you say tells how many."]},{"id":"r3","mode":"count","prompt":"How many apples now?","visual":"🍏","total":3,"choices":[3,4,5],"hints":["Touch each apple once."]}]}'::jsonb,'published','reviewed',1,3) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
