e"],"reply":"A doll! What is your doll''s favourite thing to do?"},{"id":"blocks","keywords":["block","lego","brick"],"reply":"Blocks! What do you like to build?"}],"quickReplies":[{"id":"q1","visual":"🧸","say":"My teddy","conceptId":"teddy"},{"id":"q2","visual":"🚗","say":"My car","conceptId":"car"},{"id":"q3","visual":"🧱","say":"My blocks","conceptId":"blocks"},{"id":"q4","visual":"🪆","say":"My doll","conceptId":"doll"}],"modelSentence":"My favourite toy is my teddy because it is soft.","fallbackReply":"That sounds like a fun toy! What do you like about it?","followUps":["What do you like to do with it?","Why do you like it?"],"maxTurns":3,"hints":[]}]}'::jsonb,'published','reviewed',1,3) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
