insert into public.activities (id,title,description,domain_id,world,engine_type,age_band,difficulty,configuration,status,review_status,version,estimated_duration) values ('ask-the-character-a-question','Ask the Character a Question','Choose or say a question to ask Otto the Owl.','conversation','conversation-cafe','listen-respond','little-explorer',2,'{"id":"ask-the-character-a-question","title":"Ask the Character a Question","description":"Choose or say a question to ask Otto the Owl.","world":"conversation-cafe","domain":"conversation","objectiveIds":["CONV-QST-01"],"ageBand":"little-explorer","difficulty":2,"instructions":"Otto the Owl is happy to answer. What would you like to ask?","audioInstructions":"Otto the Owl is happy to answer. What would you like to ask?","estimatedMinutes":3,"feedback":{"correct":["Good thinking!","You noticed something interesting!","Lovely work!","Yes, you did it!"],"encourage":["Let''s try together.","Would you like a little hint?","Let''s look at it another way.","Nice try! One more go."],"complete":["You worked hard on that.","What a wonderful adventure!","Thank you for playing with me."]},"accessibility":{"requiresSpeech":false,"tapAlternative":true,"reducedMotionSafe":true},"media":[],"completion":{"minRoundsCompleted":1},"frameworkMappings":[{"frameworkId":"eyfs","reference":"Communication and language","mappingType":"aligns"},{"frameworkId":"ncf-fs","reference":"Cognitive development (exploring the world)","mappingType":"aligns"}],"characterId":"otto","tags":["questions","owl"],"status":"published","reviewStatus":"reviewed","version":1,"engine":"listen-respond","rounds":[{"id":"r1","prompt":"Hoo hoo! I am Otto. You can ask me a question. What would you like to know?","display":"🦉","concepts":[{"id":"sleep","keywords":["sleep","night","awake"],"reply":"Owls like to be awake at night and sleep in the day. Great question! What do you do at night?"},{"id":"food","keywords":["eat","food","hungry"],"reply":"I eat little mice and bugs. Great question! What do you like to eat?"},{"id":"why","keywords":["why","how"],"reply":"What a thinking question! I wonder about that too. Can you guess the answer?"},{"id":"fly","keywords":["fly","wings"],"reply":"My wings are soft, so I fly quietly! What can you do quietly?"}],"quickReplies":[{"id":"q1","visual":"🌙","say":"Do you sleep at night?","conceptId":"sleep"},{"id":"q2","visual":"🍽️","say":"What do you eat?","conceptId":"food"},{"id":"q3","visual":"🪽","say":"How do you fly?","conceptId":"fly"},{"id":"q4","visual":"❓","say":"Why do owls say hoo?","conceptId":"why"}],"modelSentence":"Otto, what do you eat?","fallbackReply":"Great question! I will think about that. Do you want to ask me another one?","followUps":[],"maxTurns":2,"hints":[]}]}'::jsonb,'published','reviewed',1,3) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
