insert into public.activities (id,title,description,domain_id,world,engine_type,age_band,difficulty,configuration,status,review_status,version,estimated_duration) values ('what-happens-next','What Happens Next?','Look at a little story and say what might happen next.','conversation','conversation-cafe','listen-respond','little-explorer',2,'{"id":"what-happens-next","title":"What Happens Next?","description":"Look at a little story and say what might happen next.","world":"conversation-cafe","domain":"conversation","objectiveIds":["CONV-NAR-02"],"ageBand":"little-explorer","difficulty":2,"instructions":"What do you think will happen next? Any idea is a good idea!","audioInstructions":"What do you think will happen next? Any idea is a good idea!","estimatedMinutes":3,"feedback":{"correct":["Good thinking!","You noticed something interesting!","Lovely work!","Yes, you did it!"],"encourage":["Let''s try together.","Would you like a little hint?","Let''s look at it another way.","Nice try! One more go."],"complete":["You worked hard on that.","What a wonderful adventure!","Thank you for playing with me."]},"accessibility":{"requiresSpeech":false,"tapAlternative":true,"reducedMotionSafe":true},"media":[],"completion":{"minRoundsCompleted":2},"frameworkMappings":[{"frameworkId":"eyfs","reference":"Communication and language","mappingType":"aligns"},{"frameworkId":"ncf-fs","reference":"Language and literacy","mappingType":"aligns"}],"characterId":"otto","tags":["predict"],"status":"published","reviewStatus":"reviewed","version":1,"engine":"listen-respond","rounds":[{"id":"r1","prompt":"The balloon slipped out of the girl''s hand. What might happen next?","display":"🎈","concepts":[{"id":"float","keywords":["float","fly","up","sky","away"],"reply":"Yes, it might float up into the sky! What would you do?"},{"id":"catch","keywords":["catch","get","jump","grab"],"reply":"Good idea! She might jump and try to catch it."},{"id":"pop","keywords":["pop","burst","bang"],"reply":"Pop! That could happen if it touches something sharp."}],"quickReplies":[{"id":"q1","visual":"⬆️","say":"It floats up","conceptId":"float"},{"id":"q2","visual":"🙌","say":"She catches it","conceptId":"catch"},{"id":"q3","visual":"💥","say":"It pops","conceptId":"pop"}],"modelSentence":"I think the balloon will float away.","fallbackReply":"That is a creative idea! Tell me more.","followUps":[],"maxTurns":2,"hints":[]},{"id":"r2","prompt":"It started to rain, and the puppy has no umbrella. What might happen next?","display":"🐶","concepts":[{"id":"wet","keywords":["wet","soaked","splash"],"reply":"He might get wet and splashy! What could help him?"},{"id":"home","keywords":["home","house","inside","run"],"reply":"He might run home! Good thinking."},{"id":"umbrella","keywords":["umbrella","coat","hat"],"reply":"An umbrella would help! Where could he find one?"}],"quickReplies":[{"id":"q1","visual":"💦","say":"He gets wet","conceptId":"wet"},{"id":"q2","visual":"🏠","say":"He runs home","conceptId":"home"},{"id":"q3","visual":"☂️","say":"He finds an umbrella","conceptId":"umbrella"}],"modelSentence":"I think the puppy will run home.","fallbackReply":"Thank you for telling me! That is interesting.","followUps":[],"maxTurns":2,"hints":[]}]}'::jsonb,'published','reviewed',1,3) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
