:"Dogs are playful! Now you can ask me something!"},{"id":"elephant","keywords":["elephant"],"reply":"Elephants are enormous! Now you can ask me something!"},{"id":"rabbit","keywords":["rabbit","bunny"],"reply":"Bunnies hop! Now you can ask me something!"}],"quickReplies":[{"id":"q1","visual":"🐱","say":"A cat","conceptId":"cat"},{"id":"q2","visual":"🐶","say":"A dog","conceptId":"dog"},{"id":"q3","visual":"🐘","say":"An elephant","conceptId":"elephant"},{"id":"q4","visual":"🐰","say":"A bunny","conceptId":"rabbit"}],"modelSentence":"My favourite animal is a cat. What is yours?","fallbackReply":"That is a good one! Now you can ask me a question.","followUps":["You can ask me: what is your favourite animal?"],"maxTurns":3,"hints":[]}]}'::jsonb,'published','reviewed',1,3) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
