ly":"That is a great reason!"}],"quickReplies":[{"id":"q1","visual":"🛝","say":"The park because I like swings","conceptId":"park"},{"id":"q2","visual":"🏖️","say":"The beach because I like sand","conceptId":"beach"}],"modelSentence":"I would like to go to the park because I like the swings.","fallbackReply":"Thank you for sharing your idea!","followUps":["Why do you like it?"],"maxTurns":2,"hints":[]}]}'::jsonb,'published','reviewed',1,3) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
