e it keeps us warm.","fallbackReply":"That is an interesting idea! A coat also keeps us warm.","followUps":[],"maxTurns":2,"hints":[]},{"id":"r2","prompt":"Why do we brush our teeth?","display":"🪥","concepts":[{"id":"clean","keywords":["clean","healthy","germs","bugs","cavity","sugar","strong"],"reply":"Yes, it keeps our teeth clean and strong!"}],"quickReplies":[{"id":"q1","visual":"✨","say":"To keep them clean","conceptId":"clean"},{"id":"q2","visual":"🦷","say":"So they stay strong","conceptId":"clean"}],"modelSentence":"We brush our teeth to keep them clean.","fallbackReply":"Thank you for telling me! That is interesting.","followUps":[],"maxTurns":2,"hints":[]}]}'::jsonb,'published','reviewed',1,3) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
